#include "CitizenStatusRuntime.hpp"
namespace elysium::citizens {bool CitizenStatusRuntime::addDef(StatusDef d,std::string&w){if(!d.id||!d.version){w="invalid status def";return false;}return defs_.emplace(d.id,std::move(d)).second;}bool CitizenStatusRuntime::apply(ActiveStatus s,std::string&w){auto d=defs_.find(s.def);if(d==defs_.end()||!s.id||!s.subject){w="invalid status";return false;}s.severity=std::clamp(std::isfinite(s.severity)?s.severity:0.0,0.0,1.0);if(d->second.stacking==StackPolicy::Exclusive&&d->second.group){for(auto i=active_.begin();i!=active_.end();)if(i->second.subject==s.subject){auto od=defs_.find(i->second.def);if(od!=defs_.end()&&od->second.group==d->second.group)i=active_.erase(i);else++i;}else{} }if(d->second.stacking==StackPolicy::SeverityReplace){for(auto&[_,a]:active_)if(a.subject==s.subject&&a.def==s.def){if(s.severity>a.severity)a=s;return true;}}if(d->second.stacking==StackPolicy::Refresh){for(auto&[_,a]:active_)if(a.subject==s.subject&&a.def==s.def){a.start=s.start;a.expiry=s.expiry;a.severity=s.severity;return true;}}active_[s.id]=s;return true;}void CitizenStatusRuntime::expire(std::uint64_t t){for(auto i=active_.begin();i!=active_.end();)if(i->second.expiry&&i->second.expiry<=t)i=active_.erase(i);else++i;}std::vector<ActiveStatus>CitizenStatusRuntime::forSubject(StableId s)const{std::vector<ActiveStatus>v;for(auto&[_,a]:active_)if(a.subject==s)v.push_back(a);std::sort(v.begin(),v.end(),[](auto&a,auto&b){return a.def==b.def?a.id<b.id:a.def<b.def;});return v;}}
